import { revalidateTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export default async function Page() {
  const products = await getAllProducts()

  async function syncCatalog() {
    'use server'

    // Trigger the upstream ERP/PIM sync here, then mark the catalog cache
    // stale so it's recomputed in the background. Using the same "max"
    // profile as the cache itself keeps this a background (non-blocking)
    // refresh: this request returns immediately, and any view reading the
    // "products" tag converges to fresh data shortly after.
    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Products</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

